import pyomo.environ as pyo

DATA = {
    "cities": [1, 2, 3, 4, 5, 6],
    "start": 1,
    "cost": {
        (1, 2): 86, (1, 3): 81, (1, 4): 64, (1, 5): 65, (1, 6): 24,
        (2, 1): 86, (2, 3): 44, (2, 4): 80, (2, 5): 91, (2, 6): 23,
        (3, 1): 81, (3, 2): 44, (3, 4): 15, (3, 5): 25, (3, 6): 89,
        (4, 1): 64, (4, 2): 80, (4, 3): 15, (4, 5): 89, (4, 6): 41,
        (5, 1): 65, (5, 2): 91, (5, 3): 25, (5, 4): 89, (5, 6): 29,
        (6, 1): 24, (6, 2): 23, (6, 3): 89, (6, 4): 41, (6, 5): 29,
    },
}


def build_model(data=None):
    d = data or DATA
    cities = d["cities"]
    start = d["start"]
    cost = d["cost"]
    n = len(cities)

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=cities)
    model.Arcs = pyo.Set(
        initialize=[(i, j) for i in cities for j in cities if i != j],
        dimen=2,
    )

    model.x = pyo.Var(model.Arcs, domain=pyo.Binary)
    model.u = pyo.Var(model.I, domain=pyo.NonNegativeReals, bounds=(1, n))

    def obj_rule(m):
        return sum(cost[(i, j)] * m.x[i, j] for (i, j) in m.Arcs)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def out_rule(m, i):
        return sum(m.x[i, j] for j in cities if j != i) == 1

    model.out_arc = pyo.Constraint(model.I, rule=out_rule)

    def in_rule(m, j):
        return sum(m.x[i, j] for i in cities if i != j) == 1

    model.in_arc = pyo.Constraint(model.I, rule=in_rule)

    def mtz_rule(m, i, j):
        if i == start or j == start:
            return pyo.Constraint.Skip
        return m.u[j] >= m.u[i] + 1 - n * (1 - m.x[i, j])

    model.subtour = pyo.Constraint(model.Arcs, rule=mtz_rule)

    def start_order_rule(m):
        return m.u[start] == 1

    model.start_order = pyo.Constraint(rule=start_order_rule)

    return model


